def _fraction_from_parts(
    negative: bool,
    digits: str,
    decimal_places: int,
    exponent: int,
) -> tuple[int, int]:
    """Build ``(numerator, denominator)`` from decimal significand parts."""
    significand = int(digits) if digits else 0
    if negative:
        significand = -significand
    power = exponent - decimal_places
    if power >= 0:
