    """Nearest lattice integer for ``scale * numerator / denominator``."""
    scaled_num = numerator * scale
    if scaled_num >= 0:
        return (2 * scaled_num + denominator) // (2 * denominator)
    return -((-2 * scaled_num + denominator) // (2 * denominator))


